"""Laporan akhir sebagai dokumen bertanda tangan ber-QR (R-19, P6-4): snapshot + SHA-256, terkunci setelah disetujui,
dan `verify_signature_qr` mendeteksi DOCUMENT_CHANGED untuk laporan akhir.

Revision ID: 0012_final_report_signed
Revises: 0011_views_org_local_date
Create Date: 2026-09-27
"""
from collections.abc import Sequence

from alembic import op

revision: str = "0012_final_report_signed"
